//! A shape's Rust views (types §1, crossing §2): by value, a struct or an enum
//! of owned fields; by reference, its projection, a guard at each leaf. The
//! views are generated by `shape!` from the builders here, and are this
//! crate's for tuples, `Option` and `Result`; nothing else makes a guard.

use crate::boundary::entry::Settled;
use crate::boundary::seal::ShapeViews;
use crate::boundary::signed::{Structural, tags};
use crate::boundary::uniform::Uniform;
use crate::guard::{Guard, GuardMut};
use crate::runtime::{Crosses, Runtime};

/// A shape's views (types §1): by reference its projections, shared and
/// exclusive, a guard at each leaf; by value `Owned`, a struct or an enum whose
/// every field is a `Uniform`, so each part is released or taken on its own
/// (runtime contract §1). Its methods choose the type each part is read at,
/// so it is sealed: only `shape!` and this crate implement it.
pub trait Projected<R: Runtime>: ShapeViews {
    type Ref<'a>
    where
        Self: 'a;
    type Mut<'a>
    where
        Self: 'a;
    type Owned;

    const AGGREGATE: Aggregate;

    #[doc(hidden)]
    fn project<'c>(parts: LentParts<'c, R>) -> Self::Ref<'c>
    where
        Self: 'c;
    #[doc(hidden)]
    fn project_mut<'c>(parts: LentPartsMut<'c, R>) -> Self::Mut<'c>
    where
        Self: 'c;
    #[doc(hidden)]
    fn owned(parts: OwnedParts<R>) -> Self::Owned;
}

/// The aggregate a shape is, which says how its value is taken apart: an
/// object, a tuple, or an enum, whose value is one of its variants.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Aggregate {
    Tuple,
    Object,
    Variant,
}

/// The parts of an aggregate the call lent, shared. Only the entry makes one,
/// from the aggregate's place under the call's `Settled`.
pub struct LentParts<'c, R: Runtime> {
    runtime: &'c R,
    aggregate: &'c R::Value,
    at: Settled<'c>,
}

/// The parts of an aggregate the call lent exclusively, lent together and
/// taken in the type's order.
pub struct LentPartsMut<'c, R: Runtime> {
    runtime: &'c R,
    tag: Option<u32>,
    parts: std::vec::IntoIter<&'c mut R::Value>,
    at: Settled<'c>,
}

impl<'c, R: Runtime> LentParts<'c, R> {
    pub(crate) fn of_the_entry(runtime: &'c R, aggregate: &'c R::Value, at: Settled<'c>) -> Self {
        LentParts { runtime, aggregate, at }
    }

    /// An enum's tag: its variant's place in the enum's order (types §2).
    pub fn tag(&self) -> u32 {
        self.runtime.lent_tag(self.aggregate, self.at)
    }

    /// The `i`-th part, a leaf, lent as a guard.
    pub fn leaf<T: Crosses + 'c>(&self, i: u32) -> Guard<'c, R::Shared<'c, T>> {
        let part = self.runtime.lent_part(self.aggregate, i, self.at);
        Guard::of_the_entry(self.runtime.shared(part, self.at))
    }

    /// The `i`-th part, itself a shape, lent as its projection.
    pub fn nested<P: Projected<R> + 'c>(&self, i: u32) -> P::Ref<'c> {
        P::project(LentParts::of_the_entry(self.runtime, self.place(i), self.at))
    }

    /// The `i`-th part, lent as its type crosses: a guard, or its projection.
    pub(crate) fn part<T: Structural + 'c>(&self, i: u32) -> T::Lent<'c, R> {
        T::lent(self.runtime, self.place(i), self.at)
    }

    fn place(&self, i: u32) -> &'c R::Value {
        self.runtime.lent_part(self.aggregate, i, self.at)
    }
}

impl<'c, R: Runtime> LentPartsMut<'c, R> {
    /// The parts of the aggregate `kind` at `aggregate`, and its tag where it
    /// is a variant, read before its parts are lent.
    pub(crate) fn of_the_entry(runtime: &'c R, aggregate: &'c mut R::Value, kind: Aggregate, at: Settled<'c>) -> Self {
        let tag = (kind == Aggregate::Variant).then(|| runtime.lent_tag(aggregate, at));
        let parts = runtime.lent_parts_mut(aggregate, at).collect::<Vec<_>>().into_iter();
        LentPartsMut { runtime, tag, parts, at }
    }

    /// An enum's tag: its variant's place in the enum's order (types §2).
    pub fn tag(&self) -> u32 {
        self.tag.expect("only a variant's parts have a tag")
    }

    /// The next part, a leaf, lent as a guard.
    pub fn leaf<T: Crosses + 'c>(&mut self) -> GuardMut<'c, R::Exclusive<'c, T>> {
        let place = self.next_place();
        GuardMut::of_the_entry(self.runtime.exclusive(place, self.at))
    }

    /// The next part, itself a shape, lent as its projection.
    pub fn nested<P: Projected<R> + 'c>(&mut self) -> P::Mut<'c> {
        let place = self.next_place();
        P::project_mut(LentPartsMut::of_the_entry(self.runtime, place, P::AGGREGATE, self.at))
    }

    /// The next part, lent as its type crosses.
    pub(crate) fn part<T: Structural + 'c>(&mut self) -> T::LentMut<'c, R> {
        let place = self.next_place();
        T::lent_mut(self.runtime, place, self.at)
    }

    fn next_place(&mut self) -> &'c mut R::Value {
        self.parts.next().expect("a projection lends each of its parts once")
    }
}

/// The parts of an aggregate taken apart, in the type's order (types §2).
/// Only `Uniform::into_view` makes one; a part not taken is released with it.
pub struct OwnedParts<R: Runtime> {
    tag: Option<u32>,
    parts: std::vec::IntoIter<Uniform<R, ()>>,
}

impl<R: Runtime> OwnedParts<R> {
    pub(crate) fn of_the_body(tag: Option<u32>, parts: impl Iterator<Item = R::Value>) -> Self {
        OwnedParts { tag, parts: parts.map(Uniform::of_the_crossing).collect::<Vec<_>>().into_iter() }
    }

    /// An enum's tag.
    pub fn tag(&self) -> u32 {
        self.tag.expect("only an enum's parts have a tag")
    }

    /// The next part, held at its type. Not an `Iterator`: each part is held
    /// at its own type.
    #[allow(clippy::should_implement_trait)]
    pub fn next<T>(&mut self) -> Uniform<R, T> {
        let part = self.parts.next().expect("a shape takes each of its parts once");
        Uniform::of_the_crossing(part.into_value())
    }
}

impl<R: Runtime, T: Structural> Projected<R> for Option<T> {
    type Ref<'a>
        = Option<T::Lent<'a, R>>
    where
        Self: 'a;
    type Mut<'a>
        = Option<T::LentMut<'a, R>>
    where
        Self: 'a;
    type Owned = Option<Uniform<R, T>>;

    const AGGREGATE: Aggregate = Aggregate::Variant;

    fn project<'c>(parts: LentParts<'c, R>) -> Self::Ref<'c>
    where
        Self: 'c,
    {
        match parts.tag() {
            tags::NONE => None,
            tags::SOME => Some(parts.part::<T>(0)),
            tag => unreachable!("an Option has no variant {tag}"),
        }
    }

    fn project_mut<'c>(mut parts: LentPartsMut<'c, R>) -> Self::Mut<'c>
    where
        Self: 'c,
    {
        match parts.tag() {
            tags::NONE => None,
            tags::SOME => Some(parts.part::<T>()),
            tag => unreachable!("an Option has no variant {tag}"),
        }
    }

    fn owned(mut parts: OwnedParts<R>) -> Self::Owned {
        match parts.tag() {
            tags::NONE => None,
            tags::SOME => Some(parts.next()),
            tag => unreachable!("an Option has no variant {tag}"),
        }
    }
}

impl<R: Runtime, T: Structural, E: Structural> Projected<R> for Result<T, E> {
    type Ref<'a>
        = Result<T::Lent<'a, R>, E::Lent<'a, R>>
    where
        Self: 'a;
    type Mut<'a>
        = Result<T::LentMut<'a, R>, E::LentMut<'a, R>>
    where
        Self: 'a;
    type Owned = Result<Uniform<R, T>, Uniform<R, E>>;

    const AGGREGATE: Aggregate = Aggregate::Variant;

    fn project<'c>(parts: LentParts<'c, R>) -> Self::Ref<'c>
    where
        Self: 'c,
    {
        match parts.tag() {
            tags::OK => Ok(parts.part::<T>(0)),
            tags::ERR => Err(parts.part::<E>(0)),
            tag => unreachable!("a Result has no variant {tag}"),
        }
    }

    fn project_mut<'c>(mut parts: LentPartsMut<'c, R>) -> Self::Mut<'c>
    where
        Self: 'c,
    {
        match parts.tag() {
            tags::OK => Ok(parts.part::<T>()),
            tags::ERR => Err(parts.part::<E>()),
            tag => unreachable!("a Result has no variant {tag}"),
        }
    }

    fn owned(mut parts: OwnedParts<R>) -> Self::Owned {
        match parts.tag() {
            tags::OK => Ok(parts.next()),
            tags::ERR => Err(parts.next()),
            tag => unreachable!("a Result has no variant {tag}"),
        }
    }
}

/// Tuples of parts up to twelve, each part at its place in the tuple.
macro_rules! tuple_projections {
    ($(($($p:ident $i:literal),+))+) => {$(
        impl<R: Runtime, $($p: Structural),+> Projected<R> for ($($p,)+) {
            type Ref<'a>
                = ($($p::Lent<'a, R>,)+)
            where
                Self: 'a;
            type Mut<'a>
                = ($($p::LentMut<'a, R>,)+)
            where
                Self: 'a;
            type Owned = ($(Uniform<R, $p>,)+);

            const AGGREGATE: Aggregate = Aggregate::Tuple;

            fn project<'c>(parts: LentParts<'c, R>) -> Self::Ref<'c>
            where
                Self: 'c,
            {
                ($(parts.part::<$p>($i),)+)
            }

            fn project_mut<'c>(mut parts: LentPartsMut<'c, R>) -> Self::Mut<'c>
            where
                Self: 'c,
            {
                ($(parts.part::<$p>(),)+)
            }

            fn owned(mut parts: OwnedParts<R>) -> Self::Owned {
                ($(parts.next::<$p>(),)+)
            }
        }
    )+};
}

tuple_projections! {
    (A 0)
    (A 0, B 1)
    (A 0, B 1, C 2)
    (A 0, B 1, C 2, D 3)
    (A 0, B 1, C 2, D 3, E 4)
    (A 0, B 1, C 2, D 3, E 4, F 5)
    (A 0, B 1, C 2, D 3, E 4, F 5, G 6)
    (A 0, B 1, C 2, D 3, E 4, F 5, G 6, H 7)
    (A 0, B 1, C 2, D 3, E 4, F 5, G 6, H 7, I 8)
    (A 0, B 1, C 2, D 3, E 4, F 5, G 6, H 7, I 8, J 9)
    (A 0, B 1, C 2, D 3, E 4, F 5, G 6, H 7, I 8, J 9, K 10)
    (A 0, B 1, C 2, D 3, E 4, F 5, G 6, H 7, I 8, J 9, K 10, L 11)
}
